"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Card, CardContent } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { ArrowLeft, MessageSquare, FileText, Download, Share2, Lock } from "lucide-react";

export default function RecordingPlaybackPage() {
  const params = useParams();
  const router = useRouter();
  const recordingId = params.id as string;

  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<{
    recording: any;
    chatMessages: any[];
    summary: any;
  } | null>(null);
  const [activeTab, setActiveTab] = useState<"chat" | "summary">("chat");

  const [playbackUrl, setPlaybackUrl] = useState<string | null>(null);
  const [playbackError, setPlaybackError] = useState<string | null>(null);
  const [fetchingPlaybackUrl, setFetchingPlaybackUrl] = useState(false);

  useEffect(() => {
    fetch(`/api/recordings/${recordingId}/details`)
      .then(res => res.json())
      .then(resData => {
        if (!resData.error) {
          setData(resData);
          if (resData.recording && resData.recording.status === 'completed') {
            fetchPlaybackUrl();
          }
        } else {
          setPlaybackError(resData.error);
        }
        setLoading(false);
      })
      .catch(err => {
        console.error("Failed to load recording details", err);
        setLoading(false);
      });
  }, [recordingId]);

  const fetchPlaybackUrl = async () => {
    setFetchingPlaybackUrl(true);
    setPlaybackError(null);
    try {
      const res = await fetch(`/api/recordings/${recordingId}/play`);
      const data = await res.json();
      if (res.ok) {
        setPlaybackUrl(data.playbackUrl);
      } else {
        setPlaybackError(data.error || 'Failed to authorize playback.');
      }
    } catch (error) {
      setPlaybackError('Network error connecting to playback service.');
    } finally {
      setFetchingPlaybackUrl(false);
    }
  };

  if (loading) {
    return <div className="p-8 text-center text-text-muted">Loading recording details...</div>;
  }

  if (!data || !data.recording) {
    return (
      <div className="p-8 text-center">
        <h2 className="text-xl font-bold text-red-400">Recording Not Found</h2>
        <Button onClick={() => router.push('/dashboard/recordings')} className="mt-4">Back to Recordings</Button>
      </div>
    );
  }

  const { recording, chatMessages, summary } = data;

  return (
    <div className="flex flex-col gap-6 h-[calc(100vh-80px)] pb-6">
      {/* Header */}
      <div className="flex items-center justify-between shrink-0">
        <div className="flex items-center gap-4">
          <Button variant="ghost" className="px-2" onClick={() => router.push('/dashboard/recordings')}>
            <ArrowLeft className="w-5 h-5 text-text-muted" />
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-text-primary">{recording.title}</h1>
            <p className="text-sm text-text-muted">
              Recorded on {new Date(recording.createdAt).toLocaleDateString()}
              {recording.room && ` in ${recording.room.name}`}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" className="border-border/60">
            <Share2 className="w-4 h-4 mr-2" /> Share
          </Button>
          <Button variant="outline" className="border-border/60">
            <Download className="w-4 h-4 mr-2" /> Download
          </Button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-6 flex-1 min-h-0">
        {/* Main Video Area */}
        <div className="flex-1 flex flex-col min-h-0 bg-surface rounded-2xl border border-border/60 overflow-hidden shadow-sm">
          <div className="flex-1 bg-black flex flex-col items-center justify-center relative">
            {playbackError ? (
              <div className="text-center p-6 text-white max-w-md">
                <div className="w-12 h-12 bg-red-500/20 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Lock className="w-6 h-6 text-red-400" />
                </div>
                <h3 className="text-lg font-bold mb-2">Playback Unavailable</h3>
                <p className="text-text-muted text-sm mb-6">{playbackError}</p>
                {playbackError.includes('Payment') && (
                  <Button className="w-full bg-brand-blue hover:bg-brand-blue/90 text-white shadow-lg">
                    Purchase Access
                  </Button>
                )}
                {!playbackError.includes('Payment') && (
                   <Button onClick={fetchPlaybackUrl} className="w-full">
                     Retry Access
                   </Button>
                )}
              </div>
            ) : fetchingPlaybackUrl ? (
               <div className="text-text-muted text-sm flex items-center gap-2">
                 <div className="w-4 h-4 border-2 border-brand-blue border-t-transparent rounded-full animate-spin" />
                 Authorizing Playback...
               </div>
            ) : playbackUrl ? (
              <video
                controls
                src={playbackUrl}
                className="w-full h-full max-h-full object-contain"
                poster={`https://picsum.photos/seed/${recording.id}/1920/1080`}
                onError={() => {
                  setPlaybackError("Session expired or playback failed. Please request access again.");
                  setPlaybackUrl(null);
                }}
              />
            ) : recording.status !== 'completed' ? (
              <div className="text-text-muted text-sm">Video is still processing...</div>
            ) : null}
          </div>
        </div>

        {/* Sidebar (Chat / Summary) */}
        <div className="w-full lg:w-96 shrink-0 flex flex-col bg-surface rounded-2xl border border-border/60 overflow-hidden">
          {/* Tabs */}
          <div className="flex p-2 gap-1 border-b border-border/60 shrink-0 bg-black/[0.02]">
            <button
              onClick={() => setActiveTab("chat")}
              className={`flex-1 py-2 text-sm font-medium rounded-lg flex items-center justify-center gap-2 transition-all ${
                activeTab === "chat" 
                  ? "bg-white text-brand-blue shadow-sm" 
                  : "text-text-muted hover:bg-black/5"
              }`}
            >
              <MessageSquare className="w-4 h-4" />
              Chat Log
            </button>
            <button
              onClick={() => setActiveTab("summary")}
              className={`flex-1 py-2 text-sm font-medium rounded-lg flex items-center justify-center gap-2 transition-all ${
                activeTab === "summary" 
                  ? "bg-white text-brand-blue shadow-sm" 
                  : "text-text-muted hover:bg-black/5"
              }`}
            >
              <FileText className="w-4 h-4" />
              AI Summary
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4">
            {activeTab === "chat" && (
              <div className="space-y-4">
                {chatMessages && chatMessages.length > 0 ? (
                  chatMessages.map((msg, i) => (
                    <div key={i} className="flex flex-col gap-1">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-bold text-text-primary">{msg.senderName}</span>
                        <span className="text-[10px] text-text-faint">
                          {new Date(msg.createdAt).toLocaleTimeString()}
                        </span>
                      </div>
                      <p className="text-sm text-text-secondary bg-black/[0.03] p-2 rounded-xl rounded-tl-none">
                        {msg.content}
                      </p>
                    </div>
                  ))
                ) : (
                  <div className="text-center text-text-muted mt-10 text-sm">
                    No chat messages found for this recording.
                  </div>
                )}
              </div>
            )}

            {activeTab === "summary" && (
              <div className="space-y-6">
                {summary ? (
                  <>
                    <div className="space-y-2">
                      <h3 className="text-sm font-bold text-text-primary">Executive Summary</h3>
                      <p className="text-sm text-text-secondary leading-relaxed">
                        {summary.content}
                      </p>
                    </div>
                    {summary.actionItems && summary.actionItems.length > 0 && (
                      <div className="space-y-2">
                        <h3 className="text-sm font-bold text-text-primary">Action Items</h3>
                        <ul className="space-y-2">
                          {(summary.actionItems as any[]).map((item: any, i: number) => (
                            <li key={i} className="flex gap-2 text-sm bg-brand-blue/5 p-3 rounded-xl border border-brand-blue/10">
                              <span className="text-brand-blue mt-0.5">•</span>
                              <div>
                                <p className="font-medium text-brand-blue">{item.assignee || "Unassigned"}</p>
                                <p className="text-text-secondary mt-0.5">{item.task}</p>
                              </div>
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </>
                ) : (
                  <div className="text-center text-text-muted mt-10 text-sm">
                    AI Summary is not available for this meeting.
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Card, CardContent } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { Badge } from "@/components/ui/Badge";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Video, Plus, Copy, Link2, MoreVertical,
  Users, Globe, Lock, Settings, Trash2, ExternalLink, Edit
} from "lucide-react";
import Link from "next/link";
import { useState, useEffect } from "react";
import { apiClient, Room } from "@/lib/api-client";
import { useRouter } from "next/navigation";
import { toast } from "sonner";

// Extended interface for UI properties not in API schema
interface UIRoom extends Room {
  participants: number;
  type: string;
  isLocked: boolean;
  lastUsed: string;
  color: string;
}

const containerVariants = {
  hidden: { opacity: 0 },
  show: { opacity: 1, transition: { staggerChildren: 0.06 } },
};
const itemVariants = {
  hidden: { opacity: 0, y: 16 },
  show: { opacity: 1, y: 0, transition: { type: "spring" as const, stiffness: 300, damping: 24 } },
};

export default function RoomsPage() {
  const router = useRouter();
  const [openDropdownId, setOpenDropdownId] = useState<string | null>(null);
  const [rooms, setRooms] = useState<UIRoom[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [currentUser, setCurrentUser] = useState<{name: string} | null>(null);

  useEffect(() => {
    apiClient.auth.getMe().then(user => setCurrentUser(user)).catch(() => {});
  }, []);

  const colors = [
    "from-brand-blue to-blue-500",
    "from-brand-green to-emerald-400",
    "from-amber-500 to-orange-400",
    "from-purple-500 to-pink-400"
  ];

  const handleDeleteRoom = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm("Are you sure you want to delete this room?")) return;
    try {
      await apiClient.rooms.delete(id);
      setRooms(prev => prev.filter(r => r.id !== id));
      toast.success("Room deleted successfully");
    } catch (err) {
      toast.error("Failed to delete room");
    }
  };

  const handleDuplicateRoom = async (room: UIRoom, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      const newRoom = await apiClient.rooms.create({ name: `${room.name} (Copy)`, mode: room.mode });
      const formatted: UIRoom = {
        ...newRoom,
        participants: 0,
        type: newRoom.mode === 'webinar' ? 'Webinar' : 'Meeting',
        isLocked: false,
        lastUsed: new Date(newRoom.createdAt).toLocaleDateString(),
        color: colors[rooms.length % colors.length]
      };
      setRooms(prev => [formatted, ...prev]);
      toast.success("Room duplicated successfully");
    } catch (err) {
      toast.error("Failed to duplicate room");
    }
  };

  useEffect(() => {
    apiClient.rooms.getAll()
      .then(data => {
        // Map missing UI fields until API is updated to support them
        const formatted = data.map((r, i) => ({
          ...r,
          participants: Math.floor(Math.random() * 5),
          type: r.mode === 'webinar' ? 'Webinar' : 'Meeting',
          isLocked: false,
          lastUsed: new Date(r.createdAt).toLocaleDateString(),
          color: colors[i % colors.length]
        }));
        setRooms(formatted);
      })
      .catch(console.error)
      .finally(() => setIsLoading(false));
  }, []);

  return (
    <div className="flex flex-col gap-8 pb-10">
      {/* Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-extrabold tracking-tight text-text-primary">Rooms</h1>
          <p className="text-text-muted mt-1">Create and manage your meeting rooms.</p>
        </div>
        <Link href="/dashboard/rooms/new">
          <Button className="h-11 rounded-xl px-5 bg-brand-green hover:bg-[#287854] shadow-[0_6px_20px_rgba(32,116,80,0.2)] transition-all">
            <Plus className="w-4 h-4 mr-2" />
            Create Room
          </Button>
        </Link>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        {[
          { label: "Total Rooms", value: rooms.length.toString(), icon: Video },
          { label: "Active Now", value: "0", icon: Users },
          { label: "Public", value: rooms.length.toString(), icon: Globe },
          { label: "Private", value: "0", icon: Lock },
        ].map((s, i) => (
          <div key={i} className="flex items-center gap-3 rounded-xl border border-border/60 bg-surface p-4">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-brand-green/10">
              <s.icon className="h-5 w-5 text-brand-green" />
            </div>
            <div>
              <p className="text-2xl font-bold text-text-primary">{s.value}</p>
              <p className="text-xs text-text-muted">{s.label}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Room Grid */}
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="show"
        className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"
      >
        {rooms.map((room) => (
          <motion.div key={room.id} variants={itemVariants}>
            <Card className="rounded-2xl border-border/60 bg-surface hover:shadow-lg hover:shadow-brand-blue/5 transition-all duration-300 group relative">
              {/* Gradient stripe */}
              <div className={`h-1.5 w-full rounded-t-2xl bg-gradient-to-r ${room.color}`} />

              <CardContent className="p-5 space-y-4">
                {/* Title row */}
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br ${room.color} shadow-sm`}>
                      <Video className="h-5 w-5 text-white" />
                    </div>
                    <div className="min-w-0">
                      <h3 className="text-sm font-bold text-text-primary truncate">{room.name}</h3>
                      <p className="text-xs text-text-muted truncate">/{room.slug}</p>
                    </div>
                  </div>
                  <div className="relative">
                    <button 
                      onClick={(e) => {
                        e.stopPropagation();
                        setOpenDropdownId(openDropdownId === room.id ? null : room.id);
                      }}
                      className={`flex h-7 w-7 items-center justify-center rounded-lg hover:bg-black/[0.04] text-text-muted transition-all ${openDropdownId === room.id ? 'opacity-100 bg-black/[0.04]' : 'opacity-0 group-hover:opacity-100'}`}
                    >
                      <MoreVertical className="h-4 w-4" />
                    </button>
                    
                    <AnimatePresence>
                      {openDropdownId === room.id && (
                        <>
                          <div 
                            className="fixed inset-0 z-40 cursor-default"
                            onClick={(e) => {
                              e.stopPropagation();
                              setOpenDropdownId(null);
                            }}
                          />
                          <motion.div
                            initial={{ opacity: 0, scale: 0.95, y: -10 }}
                          animate={{ opacity: 1, scale: 1, y: 0 }}
                          exit={{ opacity: 0, scale: 0.95, y: -10 }}
                          transition={{ duration: 0.15 }}
                          className="absolute right-0 top-8 w-40 rounded-xl border border-border/60 bg-surface shadow-lg shadow-black/5 z-50 overflow-hidden"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <div className="p-1.5 space-y-0.5">
                            <button 
                              onClick={(e) => { e.stopPropagation(); router.push(`/dashboard/rooms/${room.id}`); }}
                              className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-sm text-text-primary hover:bg-black/[0.04] transition-colors">
                              <Edit className="h-4 w-4 text-text-muted" /> Edit Room
                            </button>
                            <button 
                              onClick={(e) => handleDuplicateRoom(room, e)}
                              className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-sm text-text-primary hover:bg-black/[0.04] transition-colors">
                              <Copy className="h-4 w-4 text-text-muted" /> Duplicate
                            </button>
                            <div className="h-px w-full bg-border/60 my-1" />
                            <button 
                              onClick={(e) => handleDeleteRoom(room.id, e)}
                              className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-sm text-danger hover:bg-danger/10 transition-colors">
                              <Trash2 className="h-4 w-4" /> Delete
                            </button>
                          </div>
                        </motion.div>
                        </>
                      )}
                    </AnimatePresence>
                  </div>
                </div>

                {/* Meta */}
                <div className="flex items-center gap-3 text-xs text-text-muted">
                  <span className="flex items-center gap-1">
                    <Users className="h-3 w-3" /> {room.participants}
                  </span>
                  <span className="w-1 h-1 rounded-full bg-border-strong" />
                  <span>{room.type}</span>
                  <span className="w-1 h-1 rounded-full bg-border-strong" />
                  {room.isLocked ? (
                    <span className="flex items-center gap-1 text-amber-500"><Lock className="h-3 w-3" /> Locked</span>
                  ) : (
                    <span className="flex items-center gap-1 text-brand-green"><Globe className="h-3 w-3" /> Open</span>
                  )}
                </div>

                {/* Footer */}
                <div className="flex items-center justify-between pt-2 border-t border-border/40">
                  <span className="text-[11px] text-text-muted">Last used: {room.lastUsed}</span>
                  <div className="flex gap-1.5">
                    <button 
                      onClick={() => {
                        const link = `${window.location.origin}/meeting/${room.slug}`;
                        navigator.clipboard.writeText(link);
                        toast.success("Meeting link copied to clipboard");
                      }}
                      className="flex h-7 w-7 items-center justify-center rounded-lg hover:bg-brand-green/10 text-text-muted hover:text-brand-green transition-colors" 
                      title="Copy link"
                    >
                      <Copy className="h-3.5 w-3.5" />
                    </button>
                    <button 
                      onClick={(e) => {
                        e.preventDefault();
                        const hostName = currentUser?.name || "Host";
                        router.push(`/meeting/${room.slug}?name=${encodeURIComponent(hostName)}&role=host`);
                      }}
                      className="flex h-7 w-7 items-center justify-center rounded-lg hover:bg-brand-blue/10 text-text-muted hover:text-brand-blue transition-colors" 
                      title="Open room"
                    >
                      <ExternalLink className="h-3.5 w-3.5" />
                    </button>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        ))}
      </motion.div>
    </div>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import {
  ArrowLeft, Calendar as CalendarIcon, Clock, Users,
  Video, MonitorPlay, AlignLeft, Globe, Mail, X, Check,
  ChevronLeft, ChevronRight, ChevronDown, Repeat, UploadCloud, Plus
} from "lucide-react";
import { toast } from "sonner";
import Link from "next/link";
import { MOCK_ROOMS } from "@/lib/mock/schedule";
import { Select } from "@/components/ui/Select";

// ─── helpers ────────────────────────────────────────────────────────────────
const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];
const DAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

function getDaysInMonth(year: number, month: number) {
  return new Date(year, month + 1, 0).getDate();
}
function getFirstDayOfMonth(year: number, month: number) {
  return new Date(year, month, 1).getDay();
}
function fmt12(h: number, m: number) {
  const ampm = h >= 12 ? "PM" : "AM";
  const hh = h % 12 === 0 ? 12 : h % 12;
  return `${String(hh).padStart(2, "0")}:${String(m).padStart(2, "0")} ${ampm}`;
}
function addMinutes(h: number, m: number, delta: number) {
  let totalMins = h * 60 + m + delta;
  totalMins = ((totalMins % 1440) + 1440) % 1440;
  return { h: Math.floor(totalMins / 60), m: totalMins % 60 };
}

// ─── mini calendar ───────────────────────────────────────────────────────────
interface CalendarPickerProps {
  value: Date | null;
  onChange: (d: Date) => void;
  minDate?: Date;
}
function CalendarPicker({ value, onChange, minDate }: CalendarPickerProps) {
  const today = new Date();
  const [viewYear, setViewYear] = useState(value?.getFullYear() ?? today.getFullYear());
  const [viewMonth, setViewMonth] = useState(value?.getMonth() ?? today.getMonth());

  const daysInMonth = getDaysInMonth(viewYear, viewMonth);
  const firstDay = getFirstDayOfMonth(viewYear, viewMonth);
  const cells: (number | null)[] = [
    ...Array(firstDay).fill(null),
    ...Array.from({ length: daysInMonth }, (_, i) => i + 1),
  ];

  const isSelected = (day: number) =>
    value?.getFullYear() === viewYear &&
    value?.getMonth() === viewMonth &&
    value?.getDate() === day;

  const isDisabled = (day: number) => {
    if (!minDate) return false;
    const d = new Date(viewYear, viewMonth, day);
    d.setHours(0, 0, 0, 0);
    const min = new Date(minDate);
    min.setHours(0, 0, 0, 0);
    return d < min;
  };

  const isToday = (day: number) =>
    today.getFullYear() === viewYear &&
    today.getMonth() === viewMonth &&
    today.getDate() === day;

  const prevMonth = () => {
    if (viewMonth === 0) { setViewMonth(11); setViewYear(y => y - 1); }
    else setViewMonth(m => m - 1);
  };
  const nextMonth = () => {
    if (viewMonth === 11) { setViewMonth(0); setViewYear(y => y + 1); }
    else setViewMonth(m => m + 1);
  };

  return (
    <div className="w-full select-none">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <button type="button" onClick={prevMonth}
          className="h-8 w-8 flex items-center justify-center rounded-lg hover:bg-black/[0.05] transition-colors text-text-muted">
          <ChevronLeft className="h-4 w-4" />
        </button>
        <span className="text-sm font-bold text-text-primary">
          {MONTHS[viewMonth]} {viewYear}
        </span>
        <button type="button" onClick={nextMonth}
          className="h-8 w-8 flex items-center justify-center rounded-lg hover:bg-black/[0.05] transition-colors text-text-muted">
          <ChevronRight className="h-4 w-4" />
        </button>
      </div>

      {/* Day names */}
      <div className="grid grid-cols-7 mb-1">
        {DAYS.map(d => (
          <div key={d} className="text-center text-[10px] font-bold uppercase tracking-wider text-text-muted py-1">
            {d}
          </div>
        ))}
      </div>

      {/* Cells */}
      <div className="grid grid-cols-7 gap-y-0.5">
        {cells.map((day, i) => {
          if (!day) return <div key={i} />;
          const disabled = isDisabled(day);
          const selected = isSelected(day);
          const todayCell = isToday(day);
          return (
            <button
              key={i}
              type="button"
              disabled={disabled}
              onClick={() => onChange(new Date(viewYear, viewMonth, day))}
              className={`h-9 w-full rounded-lg text-sm font-medium transition-all
                ${disabled ? "text-text-muted/30 cursor-not-allowed" : "cursor-pointer"}
                ${selected
                  ? "bg-brand-green text-white shadow-md shadow-brand-green/25"
                  : todayCell && !disabled
                    ? "border border-brand-green/40 text-brand-green font-bold hover:bg-brand-green/10"
                    : !disabled
                      ? "hover:bg-brand-green/10 text-text-primary"
                      : ""}
              `}
            >
              {day}
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ─── time scrollers ──────────────────────────────────────────────────────────
interface TimePickerProps {
  hour: number;
  minute: number;
  onChange: (h: number, m: number) => void;
  label: string;
}
function TimePicker({ hour, minute, onChange, label }: TimePickerProps) {
  const hours = Array.from({ length: 24 }, (_, i) => i);
  const minutes = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55];
  const ampm = hour >= 12 ? "PM" : "AM";
  const hour12 = hour % 12 === 0 ? 12 : hour % 12;

  const hourRef = useRef<HTMLDivElement>(null);
  const minRef = useRef<HTMLDivElement>(null);

  // scroll selected into view
  useEffect(() => {
    const ITEM_H = 40;
    if (hourRef.current) hourRef.current.scrollTop = hour * ITEM_H;
  }, []);
  useEffect(() => {
    const ITEM_H = 40;
    if (minRef.current) {
      const idx = minutes.indexOf(minute) === -1 ? 0 : minutes.indexOf(minute);
      minRef.current.scrollTop = idx * ITEM_H;
    }
  }, []);

  const handleHourScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const ITEM_H = 40;
    const idx = Math.round((e.currentTarget.scrollTop) / ITEM_H);
    if (hours[idx] !== undefined) onChange(hours[idx], minute);
  };
  const handleMinScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const ITEM_H = 40;
    const idx = Math.round((e.currentTarget.scrollTop) / ITEM_H);
    if (minutes[idx] !== undefined) onChange(hour, minutes[idx]);
  };

  return (
    <div className="flex flex-col gap-2">
      <span className="text-xs font-semibold text-text-muted uppercase tracking-wider text-center">{label}</span>
      {/* Display badge */}
      <div className="flex items-center justify-center gap-1.5 mb-1">
        <span className="text-2xl font-extrabold text-text-primary tabular-nums">{String(hour12).padStart(2, "0")}</span>
        <span className="text-lg font-bold text-text-muted">:</span>
        <span className="text-2xl font-extrabold text-text-primary tabular-nums">{String(minute).padStart(2, "0")}</span>
        <span className="text-sm font-bold text-brand-green ml-1">{ampm}</span>
      </div>

      {/* Scroll wheels */}
      <div className="flex items-center gap-2 justify-center">
        {/* Hours */}
        <div className="relative">
          <div
            ref={hourRef}
            onScroll={handleHourScroll}
            className="h-[120px] w-14 overflow-y-scroll scroll-smooth snap-y snap-mandatory no-scrollbar rounded-xl border border-border/60 bg-black/[0.02]"
            style={{ scrollSnapType: "y mandatory" }}
          >
            {hours.map(h => (
              <div
                key={h}
                onClick={() => {
                  onChange(h, minute);
                  if (hourRef.current) hourRef.current.scrollTop = h * 40;
                }}
                style={{ scrollSnapAlign: "center", height: 40 }}
                className={`flex items-center justify-center text-sm font-semibold cursor-pointer transition-all
                  ${h === hour ? "text-brand-green" : "text-text-muted hover:text-text-primary"}`}
              >
                {String(h % 12 === 0 ? 12 : h % 12).padStart(2, "0")}
              </div>
            ))}
          </div>
          {/* gradient overlays */}
          <div className="pointer-events-none absolute top-0 left-0 w-full h-8 rounded-t-xl bg-gradient-to-b from-surface to-transparent" />
          <div className="pointer-events-none absolute bottom-0 left-0 w-full h-8 rounded-b-xl bg-gradient-to-t from-surface to-transparent" />
        </div>

        <span className="text-text-muted font-bold text-lg">:</span>

        {/* Minutes */}
        <div className="relative">
          <div
            ref={minRef}
            onScroll={handleMinScroll}
            className="h-[120px] w-14 overflow-y-scroll scroll-smooth snap-y snap-mandatory no-scrollbar rounded-xl border border-border/60 bg-black/[0.02]"
            style={{ scrollSnapType: "y mandatory" }}
          >
            {minutes.map(m => (
              <div
                key={m}
                onClick={() => {
                  onChange(hour, m);
                  if (minRef.current) {
                    const idx = minutes.indexOf(m);
                    minRef.current.scrollTop = idx * 40;
                  }
                }}
                style={{ scrollSnapAlign: "center", height: 40 }}
                className={`flex items-center justify-center text-sm font-semibold cursor-pointer transition-all
                  ${m === minute ? "text-brand-green" : "text-text-muted hover:text-text-primary"}`}
              >
                {String(m).padStart(2, "0")}
              </div>
            ))}
          </div>
          <div className="pointer-events-none absolute top-0 left-0 w-full h-8 rounded-t-xl bg-gradient-to-b from-surface to-transparent" />
          <div className="pointer-events-none absolute bottom-0 left-0 w-full h-8 rounded-b-xl bg-gradient-to-t from-surface to-transparent" />
        </div>

        {/* AM/PM */}
        <div className="flex flex-col gap-1">
          {["AM", "PM"].map(period => (
            <button
              key={period}
              type="button"
              onClick={() => {
                const currentAmPm = hour >= 12 ? "PM" : "AM";
                if (currentAmPm !== period) onChange(hour >= 12 ? hour - 12 : hour + 12, minute);
              }}
              className={`w-12 h-[55px] rounded-xl text-xs font-bold transition-all border
                ${ampm === period
                  ? "bg-brand-green text-white border-brand-green shadow-sm"
                  : "bg-black/[0.03] text-text-muted border-border/40 hover:border-brand-green/30 hover:text-brand-green"}
              `}
            >
              {period}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

