"use client";

/* eslint-disable react-hooks/immutability */
import React from "react";
import { cn } from "@/lib/utils";
import {
  Mic,
  MicOff,
  VideoOff,
  MonitorUp,
  Hand,
  Crown,
  Shield,
  SignalHigh,
  SignalMedium,
  SignalLow,
  Loader2,
  AlertTriangle
} from "lucide-react";
import type { Participant } from "@/lib/types/meeting";
import { useMeeting } from "@/lib/meeting-context";
import { useVideoHealth } from "../../hooks/useVideoHealth";

interface ParticipantTileProps {
  participant: Participant;
  isLarge?: boolean;
  /** When true, the tile constrains itself to 16:9 (used in filmstrips). */
  fixedAspect?: boolean;
  className?: string;
}

const roleIcon: Record<string, React.ReactNode> = {
  host: <Crown className="w-3 h-3 text-yellow-400" />,
  "co-host": <Shield className="w-3 h-3 text-blue-400" />,
};

/**
 * A single participant tile.
 *
 * The tile is *fluid* by default — it fills 100% of its parent on both axes.
 * The parent layout decides the shape (tall, wide, square). This is the key
 * difference from the old version, which forced every tile to `aspect-video`
 * regardless of context.
 *
 * Pass `fixedAspect` to opt into a 16:9 box (used in filmstrips / spotlight
 * thumbnails, where a uniform tile shape matters).
 */
export function getEffectiveVideoState(participant: Participant) {
  if (participant.audioOnlyMode) return 'audio-only';
  if (!participant.isCameraOn) return 'camera-off';
  if (participant.videoTrack) return 'video-active';
  return 'stalled';
}

export function ParticipantTile({
  participant,
  isLarge = false,
  fixedAspect = false,
  className,
}: ParticipantTileProps) {
  const { currentUser, selectedDevices, isMirrorVideoEnabled, pauseRemoteVideo, resumeRemoteVideo, isRecorderMode } = useMeeting();

  const containerRef = React.useRef<HTMLDivElement>(null);
  const videoRef = React.useRef<HTMLVideoElement>(null);
  const [isVisible, setIsVisible] = React.useState(true);
  const [playError, setPlayError] = React.useState<string | null>(null);

  React.useEffect(() => {
    if (isRecorderMode) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsVisible(true);
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => {
        setIsVisible(entry.isIntersecting);
      },
      { root: null, rootMargin: "200px" } // Preload slightly before it enters view
    );
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [isRecorderMode]);

  const isSelf = participant.id === currentUser.id;

  const handleRecover = React.useCallback(() => {
    // If recovery is triggered, we can try to re-attach the track to the srcObject
    if (videoRef.current && participant.videoTrack) {
      console.log('participant_tile_video_recovered');
      videoRef.current.srcObject = new MediaStream([participant.videoTrack]);
      videoRef.current.play().catch(e => {
        const isAbort = e.name === 'AbortError' || (e.message && e.message.includes('interrupted by a new load request'));
        if (!isAbort) {
          console.warn("Play failed on recover:", e);
          console.log('participant_tile_video_play_rejected');
          setPlayError(e.message || e.name);
        }
      });
    }
  }, [participant.videoTrack]);

  const { health, remountKey } = useVideoHealth({
    videoRef,
    track: participant.videoTrack,
    isVisible,
    onRecover: handleRecover
  });

  React.useEffect(() => {
    if (!isSelf && participant.videoTrack) {
      if (!isVisible) {
        pauseRemoteVideo(participant.videoTrack.id);
      } else {
        resumeRemoteVideo(participant.videoTrack.id);
      }
    }
  }, [isVisible, isSelf, participant.videoTrack, pauseRemoteVideo, resumeRemoteVideo]);

  const initials = participant.name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  // Camera video ref
  const lastVideoElRef = React.useRef<HTMLVideoElement | null>(null);
  const setVideoRef = React.useCallback(
    (el: HTMLVideoElement | null) => {
      // Clean up previous event listeners if needed
      if (lastVideoElRef.current) {
        lastVideoElRef.current.onloadedmetadata = null;
        lastVideoElRef.current.oncanplay = null;
      }

      videoRef.current = el;
      if (el) {
        lastVideoElRef.current = el;

        const attemptPlay = () => {
          if (!el) return;
          participant.cameraStats = participant.cameraStats || {};
          participant.cameraStats.lastVideoPlayAttemptAt = new Date().toISOString();
          
          // Force DOM properties to prevent browser autoplay blocking
          // React sometimes fails to apply the 'muted' attribute in time for play()
          el.muted = true;
          el.playsInline = true;
          
          el.play().then(() => {
             console.log('participant_tile_video_play_started');
             setPlayError(null);
             if (participant.cameraStats) {
               participant.cameraStats.lastVideoPlayResult = 'success';
               participant.cameraStats.lastVideoError = undefined;
             }
          }).catch((e) => {
            console.log('participant_tile_video_play_rejected');
            if (participant.cameraStats) {
              participant.cameraStats.lastVideoPlayResult = 'error';
              const isAbort = e.name === 'AbortError' || 
                              (e.message && e.message.includes('interrupted by a new load request'));
              if (!isAbort) {
                console.warn("Video play failed:", e);
                (el as any)._lastError = e.message || e.name;
                participant.cameraStats.lastVideoError = e.message || e.name;
                console.log('participant_tile_video_error');
                setPlayError(e.message || e.name);
              }
            }
          });
        };

        el.onloadedmetadata = attemptPlay;
        el.oncanplay = attemptPlay;

        if (participant.videoTrack) {
          if (el.srcObject) {
            const stream = el.srcObject as MediaStream;
            if (stream.getVideoTracks()[0] === participant.videoTrack) {
              attemptPlay();
              return;
            }
          }
          el.srcObject = new MediaStream([participant.videoTrack]);
          console.log('participant_tile_video_attached');
          attemptPlay();
        } else {
          el.srcObject = null;
        }
      } else {
        if (lastVideoElRef.current) lastVideoElRef.current.srcObject = null;
        lastVideoElRef.current = null;
      }
    },
    [participant.videoTrack]
  );

  // Handle Safari backgrounding/foregrounding
  React.useEffect(() => {
    const handleVisibility = () => {
      if (document.visibilityState === 'visible' && videoRef.current && participant.videoTrack) {
        // Re-bind to wake up Safari hardware pipeline
        videoRef.current.srcObject = new MediaStream([participant.videoTrack]);
        videoRef.current.play().catch(e => {
            if (e.name !== 'AbortError') console.warn("Visibility video play failed:", e);
        });
      }
    };
    document.addEventListener('visibilitychange', handleVisibility);
    window.addEventListener('pageshow', handleVisibility);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibility);
      window.removeEventListener('pageshow', handleVisibility);
    };
  }, [participant.videoTrack]);

  // Dedicated screen share ref — completely independent from camera
  const setScreenRef = React.useCallback(
    (el: HTMLVideoElement | null) => {
      if (el) {
        if (participant.screenTrack) {
          if (el.srcObject) {
            const stream = el.srcObject as MediaStream;
            if (stream.getVideoTracks()[0] === participant.screenTrack) return;
          }
          el.srcObject = new MediaStream([participant.screenTrack]);
          el.muted = true;
          el.playsInline = true;
          el.play().catch((e) => {
            if (e.name !== 'AbortError') console.warn("Screen share play failed:", e);
          });
        } else {
          el.srcObject = null;
        }
      }
    },
    [participant.screenTrack]
  );

  const effectiveVideoState = 
    (currentUser.audioOnlyMode && !isSelf) 
      ? 'audio-only' 
      : (isRecorderMode && participant.videoTrack)
          ? 'video-active'
          : getEffectiveVideoState(participant);

  const isCameraEffectivelyOn = effectiveVideoState === 'video-active' && isVisible;

  // Determine diagnosis hint
  let diagnosisHint = 'video-healthy';
  if (participant.audioOnlyMode) diagnosisHint = 'audio-only';
  else if (participant.isCameraOn === false) diagnosisHint = 'camera-off';
  else if (!participant.videoTrack && !participant.cameraStats?.consumerExists) diagnosisHint = 'no-consumer';
  else if (!participant.videoTrack && participant.cameraStats?.consumerExists) diagnosisHint = 'consumer-no-track';
  else if (participant.videoTrack && effectiveVideoState !== 'video-active') diagnosisHint = 'state-blocked-video';
  else if (participant.videoTrack && effectiveVideoState === 'video-active' && health === 'recovering') diagnosisHint = 'safari-playback-stalled';
  else if (participant.videoTrack && effectiveVideoState === 'video-active' && health === 'stalled') diagnosisHint = 'recovery-timeout-unconfirmed';

  // Mutate QA stats for diagnostics overlay
  React.useEffect(() => {
    participant.cameraStats = participant.cameraStats || {};
    
    // Check if time progressed
    if (videoRef.current) {
       const currentTime = videoRef.current.currentTime;
       if (currentTime !== (videoRef.current as any)._lastReportedTime) {
          participant.cameraStats.currentTimeProgressing = true;
          (videoRef.current as any)._lastReportedTime = currentTime;
       } else {
          participant.cameraStats.currentTimeProgressing = false;
       }
       if (health === 'healthy') {
          participant.cameraStats.lastHealthyAt = new Date().toISOString();
       }
    }
    
    participant.cameraStats.videoTrackExists = !!participant.videoTrack;
    participant.cameraStats.remoteTrackReadyState = participant.videoTrack?.readyState;
    participant.cameraStats.remoteTrackMuted = participant.videoTrack?.muted;
    participant.cameraStats.remoteTrackEnabled = participant.videoTrack?.enabled;
    participant.cameraStats.tileRenderMode = effectiveVideoState;
    participant.cameraStats.videoDimensions = videoRef.current ? `${videoRef.current.videoWidth}x${videoRef.current.videoHeight}` : '0x0';
    participant.cameraStats.currentTime = videoRef.current?.currentTime || 0;
    participant.cameraStats.readyState = videoRef.current?.readyState || 0;
    participant.cameraStats.videoElementAttached = !!videoRef.current?.srcObject;
    participant.cameraStats.isRecovering = health === 'recovering';
    participant.cameraStats.playbackRecoveryCount = remountKey;
    participant.cameraStats.diagnosisHint = diagnosisHint;
  });

  React.useEffect(() => {
    if (!participant.cameraStats) return;

    // eslint-disable-next-line react-hooks/immutability
    if (effectiveVideoState === 'video-active') {
      participant.cameraStats.tileRenderMode = 'video';
    } else if (effectiveVideoState === 'audio-only') {
      participant.cameraStats.tileRenderMode = 'audio-only';
    } else {
      participant.cameraStats.tileRenderMode = 'avatar';
    }
  }, [participant, effectiveVideoState, health]);

  const expectsMedia = isSelf || participant.isCameraOn || !participant.isMuted;
  let mediaConnectionState: string | null = null;
  
  if (expectsMedia && !currentUser.audioOnlyMode) {
    if (participant.networkQuality === 'connecting_to_media_server') {
      mediaConnectionState = "Connecting to Video";
    } else if (participant.networkQuality === 'reconnecting') {
      mediaConnectionState = "Reconnecting to Video";
    } else if (participant.isConnecting) {
      mediaConnectionState = "Connecting...";
    } else if (health === 'black') {
      mediaConnectionState = isSelf 
        ? "Your camera hardware failed. Please toggle your video off and on." 
        : "Participant's camera feed failed.";
    } else if (health === 'stalled' || (!isSelf && effectiveVideoState === 'stalled')) {
      mediaConnectionState = "Connection failed. Retrying...";
    } else if (health === 'recovering') {
      mediaConnectionState = "Reconnecting to Video";
    }
  }

  React.useEffect(() => {
    if (!participant.cameraStats) return;

    // eslint-disable-next-line react-hooks/immutability
    if (health === 'healthy') {
      participant.cameraStats.diagnosisHint = 'video-healthy';
    } else if (health === 'stalled') {
      participant.cameraStats.diagnosisHint = 'safari-playback-stalled';
    } else if (health === 'recovering') {
      participant.cameraStats.diagnosisHint = 'recovering-playback';
    }
  }, [health, participant.cameraStats]);

  return (
    <div
      ref={containerRef}
      className={cn(
        "relative w-full h-full rounded-2xl overflow-hidden group",
        "transition-shadow duration-300",
        fixedAspect && "aspect-video",
        className,
      )}
      style={{
        backgroundColor: "var(--mt-bg-tile)",
      }}
    >
      {/* ── Screen Share Overlay ──────────────────────────────────────────────
          Renders on TOP of the camera tile when screensharing is active.
          Camera feed stays alive underneath and shows as a PiP corner bubble.
      ──────────────────────────────────────────────────────────────────────── */}
      {participant.screenTrack && participant.isScreenSharing && isVisible && (
        <div className="absolute inset-0 z-20 bg-black flex items-center justify-center">
          {/* Full screen content — object-contain preserves aspect ratio */}
          <video
            ref={setScreenRef}
            autoPlay
            playsInline
            muted
            className="w-full h-full object-contain"
          />

          {/* Screen-share badge */}
          <div className="absolute top-3 left-3 z-30 bg-blue-600/90 backdrop-blur-sm rounded-full px-2 py-1 flex items-center gap-1 text-xs text-white font-medium shadow-lg">
            <MonitorUp className="w-3 h-3" />
            Screen
          </div>

          {/* PiP camera bubble — bottom-right corner */}
          {effectiveVideoState === 'video-active' && (
            <div className="absolute bottom-3 right-3 z-30 w-24 h-16 rounded-xl overflow-hidden border-2 border-white/20 shadow-xl">
              <video
                key={`pip-video-${remountKey}`}
                ref={setVideoRef}
                autoPlay
                playsInline
                muted
                className="w-full h-full object-cover"
                style={{
                  transform:
                    participant.id === currentUser.id ? "scaleX(-1)" : "none",
                }}
              />
            </div>
          )}
        </div>
      )}

      {/* ── Speaking ring (inset, never clipped by overflow-hidden parents) ── */}
      {participant.isSpeaking && !participant.isMuted && (
        <div className="absolute inset-0 z-20 pointer-events-none rounded-2xl border-[3px] border-brand-green shadow-[inset_0_0_12px_rgba(34,197,94,0.4)]" />
      )}

      {/* ── Video / avatar area ── */}
      {isCameraEffectivelyOn ? (
        <div
          className="absolute inset-0 flex items-center justify-center"
          style={
            isLarge
              ? { backgroundColor: "#111111" }
              : {
                  background:
                    "linear-gradient(135deg, var(--mt-bg-tile-camera), var(--mt-bg-tile), var(--mt-bg-tile-alt2))",
                }
          }
        >
          <video
            key={`main-video-${remountKey}`}
            ref={setVideoRef}
            autoPlay
            playsInline
            muted
            className={cn(
              "w-full h-full",
              "object-cover",
              health === 'recovering' && "opacity-50"
            )}
            style={{
              transform:
                isSelf && isMirrorVideoEnabled ? "scaleX(-1)" : "none",
            }}
          />
        </div>
      ) : (
        <div
          className="absolute inset-0 flex items-center justify-center"
          style={{
            background:
              "linear-gradient(135deg, var(--mt-bg-tile-alt), var(--mt-bg-tile), var(--mt-bg-tile-alt2))",
          }}
        >
          <div className="relative flex flex-col items-center gap-2">
            <div
              className={cn(
                "rounded-full flex items-center justify-center font-bold shadow-lg",
                isLarge ? "w-32 h-32 text-5xl" : "w-28 h-28 text-3xl",
              )}
              style={{
                backgroundColor: "var(--mt-avatar-bg, var(--mt-bg-tile-alt))",
                color: "var(--mt-avatar-text, var(--mt-text))",
                border: "3px solid rgba(255,255,255,0.18)",
              }}
            >
              {initials}
            </div>
            {participant.isSpeaking && !participant.isMuted && (
              <div className="absolute inset-0 rounded-full border-4 border-brand-green/30 animate-pulse-fast scale-110 pointer-events-none" />
            )}
          </div>
          {effectiveVideoState === 'audio-only' && (
            <div className="absolute bottom-6 flex flex-col items-center gap-1">
              <span className="text-white/80 text-xs flex items-center gap-1 bg-black/60 backdrop-blur-sm px-3 py-1 rounded-full shadow-lg">
                <SignalLow className="w-3 h-3 text-red-400" /> Audio Only
              </span>
              {participant.videoSuspendedReason === 'network' && (
                <span className="text-yellow-300 text-[10px] font-medium px-2 py-0.5 rounded-full bg-black/40">
                  Poor Network
                </span>
              )}
            </div>
          )}
        </div>
      )}

      {/* ── Hand raised ── */}
      {participant.isHandRaised && (
        <div className="absolute top-3 right-3 z-10">
          <div className="bg-yellow-500/90 backdrop-blur-sm rounded-full p-1.5 animate-bounce shadow-lg">
            <Hand className="w-4 h-4 text-white" />
          </div>
        </div>
      )}

      {/* ── Overlays (Name, Mic, Controls) ── */}
      {participant.isScreenSharing && (
        <div className="absolute top-3 left-3 z-10">
          <div className="bg-blue-500/90 backdrop-blur-sm rounded-full px-2 py-1 flex items-center gap-1 text-xs text-white font-medium">
            <MonitorUp className="w-3 h-3" />
            Sharing
          </div>
        </div>
      )}

      {/* ── Audio Connection Status (Top-right) ── */}
      {(!participant.isHandRaised) && (() => {
        // Fallback to legacy isMuted if audioConnectionStatus is missing
        const status = participant.audioConnectionStatus || (participant.isMuted ? 'muted' : 'connected');
        
        if (status === 'connected' && !participant.isMuted) return null; // Normal active mic is not shown here

        let icon = null;
        let tooltip = '';
        let wrapperClass = "bg-black/55 backdrop-blur-md rounded-full p-1.5 shadow-md";

        if (status === 'muted' || (status === 'connected' && participant.isMuted)) {
          icon = <MicOff className="w-3.5 h-3.5 text-red-500" />;
          tooltip = 'Muted';
        } else if (status === 'failed') {
          icon = <AlertTriangle className="w-3.5 h-3.5 text-red-500" />;
          tooltip = isSelf ? 'Audio connection failed' : 'Audio unavailable';
          wrapperClass = "bg-red-950/80 backdrop-blur-md rounded-full p-1.5 shadow-md border border-red-500/50";
        } else if (status === 'connecting' || status === 'reconnecting') {
          icon = <Mic className="w-3.5 h-3.5 text-amber-400 animate-pulse" />;
          tooltip = status === 'connecting' ? 'Connecting audio...' : 'Reconnecting audio...';
        }

        if (!icon) return null;

        return (
          <div className="absolute top-3 right-3 z-10" title={tooltip}>
            <div className={wrapperClass}>
              {icon}
            </div>
            {isSelf && status === 'failed' && (
              <div className="absolute top-8 right-0 bg-red-950/90 text-white text-[10px] px-2 py-1 rounded-md whitespace-nowrap border border-red-900/50">
                Check device / retry
              </div>
            )}
          </div>
        );
      })()}

      {/* ── Name pill (bottom-left, no full-width gradient strip) ── */}
      <div className="absolute bottom-3 left-3 right-3 z-10 flex items-end justify-between gap-2 pointer-events-none">
        <div
          className="flex items-center gap-1.5 min-w-0 max-w-full px-2.5 py-1 rounded-lg backdrop-blur-md"
          style={{ backgroundColor: "rgba(0,0,0,0.45)" }}
        >
          {roleIcon[participant.role] && (
            <span className="shrink-0">{roleIcon[participant.role]}</span>
          )}
          <span className="text-white text-xs font-medium truncate">
            {participant.name}
          </span>
          {isSelf && (
            <span className="text-white/60 text-[10px] shrink-0">(You)</span>
          )}
        </div>
        {/* Network quality + camera off indicators */}
        <div className="flex items-center gap-1 shrink-0">
          {!isCameraEffectivelyOn && (
            <VideoOff className="w-3.5 h-3.5 text-red-400 drop-shadow-md" />
          )}
          {participant.networkQuality === 'unstable_network' && (
            <span title="Unstable Network"><SignalMedium className="w-3.5 h-3.5 text-yellow-400 drop-shadow-md" /></span>
          )}
          {participant.networkQuality === 'poor_network' && (
            <span title="Poor Network"><SignalLow className="w-3.5 h-3.5 text-red-500 drop-shadow-md" /></span>
          )}
          {participant.networkQuality === 'device_performance_issue' && (
            <span title="Device Performance Issue"><AlertTriangle className="w-3.5 h-3.5 text-purple-400 drop-shadow-md" /></span>
          )}
          {participant.networkQuality === 'screen_share_performance_issue' && (
            <span title="Screen Share Lag"><MonitorUp className="w-3.5 h-3.5 text-orange-400 drop-shadow-md" /></span>
          )}
          {participant.networkQuality === 'good' && (
            <span title="Good Connection"><SignalHigh className="w-3.5 h-3.5 text-brand-green drop-shadow-md" /></span>
          )}
        </div>
      </div>

      {/* ── Media Connection State Overlay ── */}
      {mediaConnectionState && (
        <div className="absolute inset-0 z-[5] flex items-center justify-center bg-black/70 text-white font-medium text-sm text-center px-4">
          <div className="flex flex-col items-center gap-2">
            {health === 'black' ? (
               <AlertTriangle className="w-5 h-5 text-red-400" />
            ) : health === 'stalled' ? (
               <AlertTriangle className="w-5 h-5 text-yellow-400" />
            ) : (
               <Loader2 className="w-5 h-5 animate-spin text-brand-green" />
            )}
            <span>{mediaConnectionState}</span>
          </div>
        </div>
      )}
      {/* ── Playback Error Overlay ── */}
      {playError && participant.videoTrack && (
        <div className="absolute top-2 inset-x-2 flex flex-col items-center gap-1 z-40">
          <span className="text-white text-[10px] text-center bg-red-600/90 px-2 py-1 rounded shadow-lg border border-red-400">
            Playback Failed: {playError}
          </span>
          <button 
            onClick={(e) => {
              e.stopPropagation();
              setPlayError(null);
              if (videoRef.current) videoRef.current.play().catch(console.error);
            }}
            className="text-[10px] bg-white/20 hover:bg-white/30 px-2 py-0.5 rounded text-white cursor-pointer"
          >
            Retry
          </button>
        </div>
      )}

    </div>
  );
}

"use client";

import React from "react";
import { useMeetingTheme, type MeetingTheme } from "@/lib/meeting-theme-context";
import { useMeeting } from "@/lib/meeting-context";
import { useMeetingDevicePreferences } from "@/lib/meeting-device-preferences";
import type { GridOverflowMode } from "@/lib/types/meeting";
import {
  Speaker,
  Mic,
  Video,
  Globe,
  Volume2,
  Moon,
  Sun,
  Cloudy,
  Palette,
  Leaf,
  LayoutGrid,
  ArrowLeftRight,
  Image as ImageIcon,
  Ban,
  Droplet,
  Info,
  Bell
} from "lucide-react";
import { cn } from "@/lib/utils";

export function SettingsPanel() {
  const { theme, setTheme } = useMeetingTheme();
  const { 
    devices, 
    selectedDevices, 
    switchDevice, 
    isAINoiseSuppressionEnabled, 
    toggleAINoiseSuppression,
    isHDVideoEnabled,
    setIsHDVideoEnabled,
    isMirrorVideoEnabled,
    setIsMirrorVideoEnabled,
    isLowBandwidthEnabled,
    setIsLowBandwidthEnabled,
    isAudioOnlyModeEnabled,
    setIsAudioOnlyModeEnabled,
    isAlwaysMuteOnJoin,
    setIsAlwaysMuteOnJoin,
    vbMode,
    vbImageUrl,
    handleVbSelect,
    translationLanguage,
    setTranslationLanguage,
    captionSize,
    setCaptionSize,
    outputVolume,
    setOutputVolume,
    roomFeatureFlags,
    roomSettings,
    updateRoomSettings,
    currentUser,
    playNotificationSound
  } = useMeeting();
  const { gridOverflowMode, setGridOverflowMode } = useMeeting();
  
  const { preferences, setMeetingDevicePreferences } = useMeetingDevicePreferences();
  const nPrefs = preferences.notifications;

  return (
    <div className="flex flex-col h-full">
      <div className="px-4 py-3" style={{ borderBottom: "1px solid var(--mt-border)" }}>
        <h3 className="text-sm font-semibold" style={{ color: "var(--mt-text)" }}>Settings</h3>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar px-4 py-4 space-y-5">
        {/* Theme settings */}
        <SettingsGroup label="Theme">
          <div className="space-y-2">
            <p className="text-xs font-medium" style={{ color: "var(--mt-text-muted)" }}>
              <Palette className="w-4 h-4 inline mr-2" style={{ verticalAlign: "text-bottom" }} />
              Meeting Theme
            </p>
            <div className="grid grid-cols-4 gap-2">
              <ThemeOption
                themeName="sage"
                label="Sage"
                icon={<Leaf className="w-4 h-4" />}
                description="Fresh"
                active={theme === "sage"}
                onSelect={() => setTheme("sage")}
              />
              <ThemeOption
                themeName="midnight"
                label="Midnight"
                icon={<Moon className="w-4 h-4" />}
                description="Dark"
                active={theme === "midnight"}
                onSelect={() => setTheme("midnight")}
              />
              <ThemeOption
                themeName="soft"
                label="Soft"
                icon={<Sun className="w-4 h-4" />}
                description="Light"
                active={theme === "soft"}
                onSelect={() => setTheme("soft")}
              />
              <ThemeOption
                themeName="slate"
                label="Slate"
                icon={<Cloudy className="w-4 h-4" />}
                description="Premium"
                active={theme === "slate"}
                onSelect={() => setTheme("slate")}
              />
            </div>
          </div>
        </SettingsGroup>

        {/* Audio settings */}
        <SettingsGroup label="Audio">
          <SettingsSelect
            icon={<Mic className="w-4 h-4" />}
            label="Microphone"
            options={devices.audioInputs.map(d => ({ value: d.deviceId, label: d.label || 'Default Microphone' }))}
            value={selectedDevices.audioInput}
            onChange={(val) => switchDevice('audioInput', val)}
          />
          <SettingsSelect
            icon={<Speaker className="w-4 h-4" />}
            label="Speaker"
            options={devices.audioOutputs.map(d => ({ value: d.deviceId, label: d.label || 'Default Speaker' }))}
            value={selectedDevices.audioOutput}
            onChange={(val) => switchDevice('audioOutput', val)}
          />
          <SettingsSlider
            icon={<Volume2 className="w-4 h-4" />}
            label="Output Volume"
            value={outputVolume}
            onChange={setOutputVolume}
          />
        </SettingsGroup>

        {/* Video settings */}
        <SettingsGroup label="Video">
          <SettingsSelect
            icon={<Video className="w-4 h-4" />}
            label="Camera"
            options={devices.videoInputs.map(d => ({ value: d.deviceId, label: d.label || 'Default Camera' }))}
            value={selectedDevices.videoInput}
            onChange={(val) => switchDevice('videoInput', val)}
          />
          <SettingsToggle 
            label="HD Video" 
            checked={isHDVideoEnabled} 
            onChange={setIsHDVideoEnabled}
          />
          <SettingsToggle 
            label="Mirror my video" 
            checked={isMirrorVideoEnabled} 
            onChange={setIsMirrorVideoEnabled}
          />

          {roomFeatureFlags.virtualBackgroundEnabled && (
            <div className="pt-2 border-t" style={{ borderColor: "var(--mt-border)" }}>
              <div className="flex items-center gap-2 mb-2" style={{ color: "var(--mt-text-muted)" }}>
                <ImageIcon className="w-4 h-4" />
                <span className="text-xs font-medium">Virtual Background</span>
              </div>
            <div className="grid grid-cols-4 gap-2">
              <button
                onClick={() => handleVbSelect('none')}
                className={cn(
                  "flex flex-col items-center justify-center p-2 rounded-xl transition-all h-14",
                  vbMode === 'none' ? "ring-2 ring-brand-green bg-white/10" : "bg-white/5 hover:bg-white/10 ring-1 ring-white/10"
                )}
                title="Turn off virtual background"
              >
                <Ban className="w-5 h-5 mb-1 text-black/70" />
                <span className="text-[10px] text-black">None</span>
              </button>
              
              <button
                onClick={() => handleVbSelect('blur')}
                className={cn(
                  "flex flex-col items-center justify-center p-2 rounded-xl transition-all h-14 relative overflow-hidden",
                  vbMode === 'blur' ? "ring-2 ring-brand-green bg-white/10" : "bg-white/5 hover:bg-white/10 ring-1 ring-white/10"
                )}
                title="Blur your background"
              >
                <div className="absolute inset-0 backdrop-blur-md bg-white/5" />
                <Droplet className="relative z-10 w-5 h-5 mb-1 text-white/70" />
                <img src={`/backgrounds/blur.png`} alt={`blur`} className="w-full h-full object-cover" />
              </button>
              
              {[
                '/backgrounds/modern_office.png',
                '/backgrounds/cozy_cafe.png',
                '/backgrounds/minimalist_gradient.png'
              ].map((url, i) => (
                <button
                  key={url}
                  title={`Use Background ${i + 1}`}
                  onClick={() => handleVbSelect('image', url)}
                  className={cn(
                    "rounded-xl overflow-hidden transition-all h-14",
                    vbMode === 'image' && vbImageUrl === url ? "ring-2 ring-brand-green" : "ring-1 ring-white/10 hover:ring-white/20"
                  )}
                >
                  <img src={url} alt={`BG ${i+1}`} className="w-full h-full object-cover" />
                </button>
              ))}

              {/* Custom Upload */}
              <label 
                title="Upload custom background image"
                className={cn(
                  "flex flex-col items-center justify-center p-2 rounded-xl transition-all h-14 cursor-pointer",
                  vbMode === 'image' && vbImageUrl && !vbImageUrl.startsWith('/backgrounds') ? "ring-2 ring-brand-green bg-white/10" : "bg-white/5 hover:bg-white/10 ring-1 ring-white/10 border-dashed border-2"
                )}>
                <span className="text-lg text-black/50 leading-none mb-0.5">+</span>
                <span className="text-[9px] text-black/40">Upload</span>
                <input 
                  type="file" 
                  accept="image/*" 
                  className="hidden" 
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (!file) return;
                    const reader = new FileReader();
                    reader.onload = (ev) => {
                      handleVbSelect('image', ev.target?.result as string);
                    };
                    reader.readAsDataURL(file);
                  }} 
                />
              </label>
            </div>
            </div>
          )}
        </SettingsGroup>

        {/* Notifications */}
        <SettingsGroup label="Notifications">
          <div className="mb-4">
            <p className="text-xs mb-3" style={{ color: "var(--mt-text-muted)" }}>
              These settings are saved on this browser/device and will apply to future meetings you join from this device.
            </p>
            
            <div className="flex flex-col gap-2 p-3 rounded-md mb-4" style={{ backgroundColor: "var(--mt-bg-hover)" }}>
              <SettingsToggle 
                label="Enable all pop-up notifications" 
                checked={nPrefs.enableAllToasts} 
                onChange={(val) => setMeetingDevicePreferences({ notifications: { enableAllToasts: val } })}
              />
              <div className="flex items-center justify-between">
                <SettingsToggle 
                  label="Enable all notification sounds" 
                  checked={nPrefs.enableAllSounds} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { enableAllSounds: val } })}
                />
                <button 
                  onClick={() => playNotificationSound(800, 0.15, 0.1)} 
                  disabled={!nPrefs.enableAllSounds}
                  className="ml-2 px-2 py-1 text-[10px] uppercase font-bold rounded bg-brand-green/20 text-brand-green hover:bg-brand-green/30 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  Test
                </button>
              </div>
            </div>

            <div className="space-y-4">
              <div>
                <p className="text-[11px] font-semibold mb-2 uppercase tracking-wider" style={{ color: "var(--mt-text-faint)" }}>Chat Messages</p>
                <SettingsToggle 
                  label="Show chat message popups" 
                  checked={nPrefs.showChatToasts} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { showChatToasts: val } })}
                />
                <SettingsToggle 
                  label="Play chat message sound" 
                  checked={nPrefs.playChatSound} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { playChatSound: val } })}
                />
              </div>

              <div>
                <p className="text-[11px] font-semibold mb-2 uppercase tracking-wider" style={{ color: "var(--mt-text-faint)" }}>Participants</p>
                <SettingsToggle 
                  label="Show join/leave popups" 
                  checked={nPrefs.showJoinLeaveToasts} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { showJoinLeaveToasts: val } })}
                />
                <SettingsToggle 
                  label="Play join/leave sound" 
                  checked={nPrefs.playJoinLeaveSound} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { playJoinLeaveSound: val } })}
                />
              </div>

              <div>
                <p className="text-[11px] font-semibold mb-2 uppercase tracking-wider" style={{ color: "var(--mt-text-faint)" }}>Mute / Unmute</p>
                <SettingsToggle 
                  label="Show mute/unmute popups" 
                  checked={nPrefs.showMuteUnmuteToasts} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { showMuteUnmuteToasts: val } })}
                />
                <SettingsToggle 
                  label="Play mute/unmute sound" 
                  checked={nPrefs.playMuteUnmuteSound} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { playMuteUnmuteSound: val } })}
                />
              </div>

              <div>
                <p className="text-[11px] font-semibold mb-2 uppercase tracking-wider" style={{ color: "var(--mt-text-faint)" }}>System Notifications</p>
                <SettingsToggle 
                  label="Show system popups" 
                  checked={nPrefs.showSystemToasts} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { showSystemToasts: val } })}
                />
                <SettingsToggle 
                  label="Play system sound" 
                  checked={nPrefs.playSystemSound} 
                  onChange={(val) => setMeetingDevicePreferences({ notifications: { playSystemSound: val } })}
                />
              </div>
            </div>
          </div>
        </SettingsGroup>

        {/* General */}
        <SettingsGroup label="General">
          {roomFeatureFlags.captionsEnabled && (
            <>
              <div className="flex flex-col gap-2 pt-2 pb-3">
                <div className="flex items-center justify-between text-xs font-medium" style={{ color: "var(--mt-text-muted)" }}>
                  <span>Caption Size</span>
                  <span>{Math.round(captionSize * 100)}%</span>
                </div>
                <input 
                  type="range" 
                  min="0.5" 
                  max="2.0" 
                  step="0.1" 
                  value={captionSize} 
                  onChange={(e) => setCaptionSize(parseFloat(e.target.value))}
                  className="w-full accent-brand-green"
                />
              </div>
              <SettingsSelect
                icon={<Globe className="w-4 h-4" />}
                label="Caption Translation"
                options={[
                  { value: "original", label: "Original Language" },
                  { value: "en", label: "English" },
                  { value: "fr", label: "French" },
                  { value: "es", label: "Spanish" },
                  { value: "de", label: "German" },
                  { value: "zh", label: "Chinese" },
                  { value: "yo", label: "Yoruba" },
                  { value: "ha", label: "Hausa" },
                  { value: "ig", label: "Igbo" }
                ]}
                value={translationLanguage}
                onChange={(val) => setTranslationLanguage(val)}
              />
            </>
          )}
          <SettingsToggle 
            label="AI Noise Suppression (Premium)" 
            checked={isAINoiseSuppressionEnabled} 
            onChange={toggleAINoiseSuppression}
          />
          <SettingsToggle 
            label="Low bandwidth mode" 
            checked={isLowBandwidthEnabled} 
            onChange={setIsLowBandwidthEnabled}
          />
          <SettingsToggle 
            label="Audio-only mode" 
            checked={isAudioOnlyModeEnabled} 
            onChange={setIsAudioOnlyModeEnabled}
          />
          <SettingsToggle 
            label="Always mute on join" 
            checked={isAlwaysMuteOnJoin} 
            onChange={setIsAlwaysMuteOnJoin}
          />
        </SettingsGroup>

        {/* Display / Grid settings */}
        <SettingsGroup label="Display">
          <div>
            <div className="flex items-center gap-2 mb-2" style={{ color: "var(--mt-text-muted)" }}>
              <LayoutGrid className="w-4 h-4" />
              <span className="text-xs font-medium">Grid Overflow</span>
            </div>
            <p className="text-[10px] mb-2.5" style={{ color: "var(--mt-text-faint)" }}>
              How to handle many participants in grid view
            </p>
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => setGridOverflowMode("scroll")}
                className="flex flex-col items-center gap-1.5 p-3 rounded-xl transition-all duration-200"
                style={{
                  backgroundColor: gridOverflowMode === "scroll" ? "var(--mt-bg-active)" : "var(--mt-bg-control)",
                  border: gridOverflowMode === "scroll" ? "2px solid var(--color-brand-green)" : "2px solid var(--mt-border)",
                }}
              >
                <ArrowLeftRight className="w-4 h-4 rotate-90" style={{ color: gridOverflowMode === "scroll" ? "var(--mt-text)" : "var(--mt-text-muted)" }} />
                <span className="text-xs font-semibold" style={{ color: gridOverflowMode === "scroll" ? "var(--mt-text)" : "var(--mt-text-muted)" }}>Scroll</span>
                <span className="text-[10px]" style={{ color: "var(--mt-text-faint)" }}>Scrollbar</span>
                <span className="text-xs font-medium">Scrollable</span>
                <span className="text-[10px] text-center" style={{ color: "var(--mt-text-faint)" }}>
                  Scroll vertically through all participants
                </span>
              </button>
              <button
                onClick={() => setGridOverflowMode("paginate")}
                className="flex flex-col items-center gap-1.5 p-3 rounded-xl transition-all duration-200"
                style={{
                  backgroundColor: gridOverflowMode === "paginate" ? "var(--mt-bg-active)" : "var(--mt-bg-control)",
                  border: gridOverflowMode === "paginate" ? "2px solid var(--color-brand-green)" : "2px solid var(--mt-border)",
                }}
              >
                <span className="text-xs font-medium">Pages</span>
                <span className="text-[10px] text-center" style={{ color: "var(--mt-text-faint)" }}>
                  Show arrows to paginate through participants
                </span>
              </button>
            </div>
          </div>
        </SettingsGroup>

        {/* Media & Network (Host Only) */}
        {(currentUser.role === 'host' || currentUser.role === 'co-host') && (
          <SettingsGroup label="Media & Network">
            <SettingsToggle 
              label="Enable Network Detection" 
              checked={roomSettings.networkDetectionEnabled ?? true}
              onChange={(c) => updateRoomSettings({ networkDetectionEnabled: c })}
            />
            
            <div className="flex gap-2 my-3">
              <button onClick={() => updateRoomSettings({ poorNetworkRttMs: 300, poorNetworkLossPercent: 8, poorNetworkJitterMs: 60, networkWindowSize: 5, networkMonitorIntervalMs: 2000 })} className="text-[10px] bg-[var(--mt-bg-control)] px-2 py-1 rounded border">Default</button>
              <button onClick={() => updateRoomSettings({ poorNetworkRttMs: 1000, poorNetworkLossPercent: 25, poorNetworkJitterMs: 220, networkWindowSize: 8, networkMonitorIntervalMs: 2000 })} className="text-[10px] bg-[var(--mt-bg-control)] px-2 py-1 rounded border">Nigeria Relaxed</button>
              <button onClick={() => updateRoomSettings({ poorNetworkRttMs: 300, poorNetworkLossPercent: 5, poorNetworkJitterMs: 50, networkWindowSize: 5, networkMonitorIntervalMs: 2000 })} className="text-[10px] bg-[var(--mt-bg-control)] px-2 py-1 rounded border">Strict</button>
            </div>

            <div className="space-y-4">
              <div className="flex flex-col gap-2">
                <div className="flex items-center justify-between text-xs font-medium">
                  <span className="flex items-center gap-1">RTT Threshold (ms) <span title="Round-trip time measures how long it takes network/media packets to travel to the server and back. Higher values mean more delay."><Info className="w-3 h-3 text-brand-green"/></span></span>
                  <span>{roomSettings.poorNetworkRttMs ?? 300}ms</span>
                </div>
                <input type="range" min="100" max="3000" step="50" value={roomSettings.poorNetworkRttMs ?? 300} onChange={(e) => updateRoomSettings({ poorNetworkRttMs: parseInt(e.target.value) })} className="w-full accent-brand-green" />
              </div>

              <div className="flex flex-col gap-2">
                <div className="flex items-center justify-between text-xs font-medium">
                  <span className="flex items-center gap-1">Packet Loss (%) <span title="Packet loss means some audio/video packets are not arriving. High packet loss can cause frozen video, robotic audio or missing frames."><Info className="w-3 h-3 text-brand-green"/></span></span>
                  <span>{roomSettings.poorNetworkLossPercent ?? 8}%</span>
                </div>
                <input type="range" min="1" max="50" step="1" value={roomSettings.poorNetworkLossPercent ?? 8} onChange={(e) => updateRoomSettings({ poorNetworkLossPercent: parseFloat(e.target.value) })} className="w-full accent-brand-green" />
              </div>

              <div className="flex flex-col gap-2">
                <div className="flex items-center justify-between text-xs font-medium">
                  <span className="flex items-center gap-1">Jitter (ms) <span title="Jitter measures how inconsistent the network delay is. High jitter can cause unstable audio and video even when speed looks good."><Info className="w-3 h-3 text-brand-green"/></span></span>
                  <span>{roomSettings.poorNetworkJitterMs ?? 60}ms</span>
                </div>
                <input type="range" min="10" max="1000" step="10" value={roomSettings.poorNetworkJitterMs ?? 60} onChange={(e) => updateRoomSettings({ poorNetworkJitterMs: parseInt(e.target.value) })} className="w-full accent-brand-green" />
              </div>

              <div className="flex flex-col gap-2">
                <div className="flex items-center justify-between text-xs font-medium">
                  <span className="flex items-center gap-1">Window Size <span title="This controls how many recent samples are checked before deciding that the connection is poor. A larger window reduces false warnings."><Info className="w-3 h-3 text-brand-green"/></span></span>
                  <span>{roomSettings.networkWindowSize ?? 5}</span>
                </div>
                <input type="range" min="3" max="20" step="1" value={roomSettings.networkWindowSize ?? 5} onChange={(e) => updateRoomSettings({ networkWindowSize: parseInt(e.target.value) })} className="w-full accent-brand-green" />
              </div>

              <div className="flex flex-col gap-2">
                <div className="flex items-center justify-between text-xs font-medium">
                  <span className="flex items-center gap-1">Monitor Interval (ms) <span title="This controls how often Konn3ct checks WebRTC network stats. 2000ms means every 2 seconds."><Info className="w-3 h-3 text-brand-green"/></span></span>
                  <span>{roomSettings.networkMonitorIntervalMs ?? 2000}ms</span>
                </div>
                <input type="range" min="1000" max="10000" step="500" value={roomSettings.networkMonitorIntervalMs ?? 2000} onChange={(e) => updateRoomSettings({ networkMonitorIntervalMs: parseInt(e.target.value) })} className="w-full accent-brand-green" />
              </div>
            </div>
          </SettingsGroup>
        )}
      </div>
    </div>
  );
}

function ThemeOption({
  themeName,
  label,
  icon,
  description,
  active,
  onSelect,
}: {
  themeName: MeetingTheme;
  label: string;
  icon: React.ReactNode;
  description: string;
  active: boolean;
  onSelect: () => void;
}) {
  return (
    <button
      onClick={onSelect}
      className="flex flex-col items-center gap-1.5 p-3 rounded-xl transition-all duration-200"
      style={{
        backgroundColor: active ? "var(--mt-bg-active)" : "var(--mt-bg-control)",
        border: active ? "2px solid var(--color-brand-green)" : "2px solid var(--mt-border)",
      }}
    >
      <div
        className="w-full aspect-[16/10] rounded-lg flex items-center justify-center"
        style={{
          backgroundColor:
            themeName === "sage" ? "#F2F5F2" :
            themeName === "midnight" ? "#18181B" :
            themeName === "slate" ? "#0F172A" : "#F0EFE9",
          border: "1px solid var(--mt-border)",
        }}
      >
        <div className="flex gap-1">
          <div
            className="w-6 h-4 rounded"
            style={{
              backgroundColor:
                themeName === "sage" ? "#9DB8A3" :
                themeName === "midnight" ? "#27272A" :
                themeName === "slate" ? "#1E293B" : "#E3E2DC",
            }}
          />
          <div
            className="w-6 h-4 rounded"
            style={{
              backgroundColor:
                themeName === "sage" ? "#9DB8A3" :
                themeName === "midnight" ? "#27272A" :
                themeName === "slate" ? "#1E293B" : "#E3E2DC",
            }}
          />
        </div>
      </div>
      <div className="flex items-center gap-1.5">
        <span style={{ color: active ? "var(--mt-text)" : "var(--mt-text-muted)" }}>{icon}</span>
        <span
          className="text-xs font-semibold"
          style={{ color: active ? "var(--mt-text)" : "var(--mt-text-muted)" }}
        >
          {label}
        </span>
      </div>
      <span
        className="text-[10px]"
        style={{ color: "var(--mt-text-faint)" }}
      >
        {description}
      </span>
    </button>
  );
}

function SettingsGroup({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <p
        className="text-[11px] uppercase tracking-wider font-semibold mb-3"
        style={{ color: "var(--mt-text-faint)" }}
      >
        {label}
      </p>
      <div className="space-y-3">{children}</div>
    </div>
  );
}

function SettingsSelect({
  icon,
  label,
  options,
  value,
  onChange,
}: {
  icon: React.ReactNode;
  label: string;
  options: { value: string; label: string }[];
  value?: string;
  onChange?: (val: string) => void;
}) {
  return (
    <div>
      <div className="flex items-center gap-2 mb-1.5" style={{ color: "var(--mt-text-muted)" }}>
        {icon}
        <span className="text-xs font-medium">{label}</span>
      </div>
      <select
        value={value}
        onChange={(e) => onChange?.(e.target.value)}
        className="w-full rounded-xl px-3 py-2 text-xs outline-none transition-colors appearance-none"
        style={{
          backgroundColor: "var(--mt-bg-input)",
          border: "1px solid var(--mt-border)",
          color: "var(--mt-text-secondary)",
        }}
      >
        {options.length === 0 && <option value="">No devices found</option>}
        {options.map((o) => (
          <option key={o.value} value={o.value} style={{ backgroundColor: "var(--mt-option-bg)" }}>
            {o.label}
          </option>
        ))}
      </select>
    </div>
  );
}

function SettingsToggle({
  label,
  checked,
  onChange,
}: {
  label: string;
  checked: boolean;
  onChange?: (val: boolean) => void;
}) {
  const [isOnLocal, setIsOnLocal] = React.useState(checked);
  const isOn = onChange ? checked : isOnLocal;

  const handleClick = () => {
    const newVal = !isOn;
    if (onChange) onChange(newVal);
    else setIsOnLocal(newVal);
  };

  return (
    <div className="flex items-center justify-between py-1">
      <span className="text-xs" style={{ color: "var(--mt-text-muted)" }}>{label}</span>
      <button
        onClick={handleClick}
        className={`relative w-9 h-5 rounded-full transition-colors duration-200 ${
          isOn ? "bg-brand-green" : ""
        }`}
        style={!isOn ? { backgroundColor: "var(--mt-bg-control-hover)" } : undefined}
      >
        <span
          className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white transition-transform duration-200 ${
            isOn ? "translate-x-4" : ""
          }`}
        />
      </button>
    </div>
  );
}

function SettingsSlider({
  icon,
  label,
  value,
  onChange,
}: {
  icon: React.ReactNode;
  label: string;
  value: number;
  onChange?: (val: number) => void;
}) {
  const [val, setVal] = React.useState(value);

  React.useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setVal(value);
  }, [value]);

  return (
    <div>
      <div className="flex items-center gap-2 mb-2" style={{ color: "var(--mt-text-muted)" }}>
        {icon}
        <span className="text-xs font-medium">{label}</span>
        <span className="ml-auto text-xs font-semibold">{val}%</span>
      </div>
      <input
        type="range"
        min="0"
        max="100"
        value={val}
        onChange={(e) => {
          const newVal = parseInt(e.target.value, 10);
          setVal(newVal);
          onChange?.(newVal);
        }}
        className="w-full accent-brand-green bg-black/20 h-1.5 rounded-lg appearance-none cursor-pointer"
      />
    </div>
  );
}

